import app from 'flarum/admin/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import errorHandler from '../utils/errorHandler';
export default class WhyNotModal extends Modal {
  loading = true;
  whyNot = null;
  className() {
    return 'Modal--large WhyNotModal';
  }
  title() {
    return app.translator.trans('flarum-extension-manager.admin.why_not_modal.title');
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.requestWhyNot();
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, this.loading ? m(LoadingIndicator, null) : m("pre", {
      className: "WhyNotModal-contents"
    }, this.whyNot));
  }
  requestWhyNot() {
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/extension-manager/why-not`,
      body: {
        data: {
          package: this.attrs.package
        }
      }
    }).then(response => {
      this.loading = false;
      this.whyNot = response.data.reason;
      m.redraw();
    }).catch(errorHandler);
  }
}
flarum.reg.add('flarum-extension-manager', 'admin/components/WhyNotModal', WhyNotModal);